def get_rules():
    rows = data_rows('W0::Rules', {'B': 'string', 'C': 'string', 'D': 'number'})
    return [(cell('W0::Rules', f'B{r}'), cell('W0::Rules', f'C{r}'), int(num('W0::Rules', f'D{r}'))) for r in rows]

def get_costs():
    rows = data_rows('W0::Leaf costs', {'E': 'string', 'F': 'number'})
    return {cell('W0::Leaf costs', f'E{r}'): float(num('W0::Leaf costs', f'F{r}')) for r in rows}

rules = get_rules()
costs = get_costs()

children_map = {}
for p, c, mult in rules:
    if p not in children_map:
        children_map[p] = []
    children_map[p].append((c, mult))

def expand(part):
    if part in costs:
        return {part: 1}
    if part not in children_map:
        return {}
    res = {}
    for child, mult in children_map[part]:
        sub = expand(child)
        for leaf, count in sub.items():
            res[leaf] = res.get(leaf, 0) + count * mult
    return res

beacon_leaves = expand('Beacon')
part_costs = {leaf: count * costs[leaf] for leaf, count in beacon_leaves.items() if leaf in costs}
max_cost = max(part_costs.values())
best_parts = sorted([p for p, c in part_costs.items() if c == max_cost])
result = best_parts[0]

